    rule [keccak-mappings-overlap-false-ml]: { keccak(A) +Int B #Equals keccak(C) } => { true #Equals keccak(A) +Int B ==Int keccak(C) } requires notBool (A ==K C) [symbolic(A, C), concrete(B), simplification, comm]

